-- ── hand-amended: the CHECKs (migration SQL only) ──────────────────────────
-- Postgres evaluates a row's CHECKs in NAME order; each refused probe below
-- violates only its target. Every nullable column says IS NULL first
-- (guide §3). Mirrored by the commands' named 400s (`dock-door.command.ts`,
-- `dock-schedule.command.ts`, `dock-appointment.command.ts`).
--
-- dock_doors — decision 1: an uppercased code, an optional trimmed name.
ALTER TABLE "dock_doors" ADD CONSTRAINT "dock_doors_code_format" CHECK ("code" ~ '^[A-Z0-9-]{1,20}$');--> statement-breakpoint
ALTER TABLE "dock_doors" ADD CONSTRAINT "dock_doors_name_length" CHECK (
	"name" IS NULL OR (char_length("name") BETWEEN 1 AND 60 AND "name" = btrim("name"))
);--> statement-breakpoint
-- dock_schedules — decision 3: the slot length, the IST hours on its grid
-- (`closes_minute` 1440 = 24:00), the ISO weekday bitmask, the grace.
ALTER TABLE "dock_schedules" ADD CONSTRAINT "dock_schedules_slot_check" CHECK ("slot_minutes" IN (15, 30, 60));--> statement-breakpoint
ALTER TABLE "dock_schedules" ADD CONSTRAINT "dock_schedules_hours_range" CHECK (
	0 <= "opens_minute" AND "opens_minute" < "closes_minute" AND "closes_minute" <= 1440
);--> statement-breakpoint
ALTER TABLE "dock_schedules" ADD CONSTRAINT "dock_schedules_hours_on_grid" CHECK (
	"opens_minute" % "slot_minutes" = 0 AND "closes_minute" % "slot_minutes" = 0
);--> statement-breakpoint
ALTER TABLE "dock_schedules" ADD CONSTRAINT "dock_schedules_open_days_range" CHECK ("open_days" BETWEEN 1 AND 127);--> statement-breakpoint
ALTER TABLE "dock_schedules" ADD CONSTRAINT "dock_schedules_grace_range" CHECK ("grace_minutes" BETWEEN 0 AND 120);--> statement-breakpoint
-- dock_appointments — decisions 4, 6, 7, 14.
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_code_format" CHECK ("code" ~ '^DA-[0-9]{4,9}$');--> statement-breakpoint
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_status_check" CHECK (
	"status" IN ('booked', 'arrived', 'cancelled')
