-- 1 to 8 slots of at most 60 minutes: never empty, never past 8 hours.
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_window_check" CHECK (
	"ends_at" > "starts_at" AND "ends_at" - "starts_at" <= interval '8 hours'
