ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_transporter_name_length" CHECK (
	"transporter_name" IS NULL OR (char_length("transporter_name") BETWEEN 1 AND 80 AND "transporter_name" = btrim("transporter_name"))
);--> statement-breakpoint
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_note_length" CHECK (
	"note" IS NULL OR (char_length("note") BETWEEN 1 AND 500 AND "note" = btrim("note"))
