-- Decision 8 — arrived ⇔ linked to a gate-in, with when and by whom.
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_arrived_pairing" CHECK (
	("status" = 'arrived') = ("gate_in_id" IS NOT NULL)
	AND ("gate_in_id" IS NULL) = ("linked_at" IS NULL)
	AND ("linked_at" IS NULL) = ("linked_by" IS NULL)
