-- Decision 7 — cancelled ⇔ the instant, the canceller and the reason.
ALTER TABLE "dock_appointments" ADD CONSTRAINT "dock_appointments_cancelled_pairing" CHECK (
	("status" = 'cancelled') = ("cancelled_at" IS NOT NULL)
	AND ("cancelled_at" IS NULL) = ("cancelled_by" IS NULL)
