ALTER TABLE "dock_appointment_documents" ADD CONSTRAINT "dock_appointment_documents_one_document" CHECK (num_nonnulls("po_id", "asn_id") = 1);--> statement-breakpoint
ALTER TABLE "dock_appointment_documents" ADD CONSTRAINT "dock_appointment_documents_position_range" CHECK ("position" BETWEEN 0 AND 9);--> statement-breakpoint
-- ── hand-amended: RLS (migration SQL only) ─────────────────────────────────
-- The doors and the schedule: the plain tenant arm (0086).
ALTER TABLE "dock_doors" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "dock_doors_tenant_isolation" ON "dock_doors"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
ALTER TABLE "dock_schedules" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "dock_schedules_tenant_isolation" ON "dock_schedules"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- The appointments: the AD-24 arm (0064's advance_shipment_notices) — an
-- operator session sees the tenant; a portal session only its own client's,
-- and never a null-client (mixed or document-less) appointment.
ALTER TABLE "dock_appointments" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "dock_appointments_tenant_isolation" ON "dock_appointments"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
-- The documents ride the parent (0064's asn_lines).
ALTER TABLE "dock_appointment_documents" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "dock_appointment_documents_tenant_isolation" ON "dock_appointment_documents"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR EXISTS (
				SELECT 1 FROM "dock_appointments" a
				WHERE a."tenant_id" = "dock_appointment_documents"."tenant_id" AND a."id" = "dock_appointment_documents"."appointment_id"
			)
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR EXISTS (
				SELECT 1 FROM "dock_appointments" a
				WHERE a."tenant_id" = "dock_appointment_documents"."tenant_id" AND a."id" = "dock_appointment_documents"."appointment_id"
			)
		)
	);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0109 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction — a valid
-- base row, then the one change under test — and must be refused BY ITS
-- NAMED CONSTRAINT (guide §3, CHECKs in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	d uuid := gen_random_uuid();
	g uuid := gen_random_uuid();
	a uuid := gen_random_uuid();
	r uuid;
	n integer := 0;
	refused_by text;
	expected text;
	probe text;
	tbl text;
BEGIN
	FOREACH tbl IN ARRAY ARRAY['dock_doors', 'dock_schedules', 'dock_appointments', 'dock_appointment_documents'] LOOP
		IF NOT (SELECT relrowsecurity FROM pg_class WHERE relname = tbl AND relkind = 'r') THEN
			RAISE EXCEPTION 'migration 0110: row level security is not enabled on %.', tbl;
		END IF;
	END LOOP;
	-- (1) accepted shapes: an active door with a name and an inactive one
	-- without; schedules on every slot length, including 00:00–24:00 on the
	-- hour grid, one open day and all seven, grace 0 and 120; a booked
	-- appointment bare and one with every optional field, an exactly-8-hour
	-- window and a nine-digit code; an arrived and a cancelled one; a PO and
	-- an ASN document at positions 0 and 9.
	BEGIN
		INSERT INTO "dock_doors" ("id","tenant_id","warehouse_id","code","name","active","created_by")
		VALUES (d, t, w, 'D-3', 'North dock 3', true, u),
		       (gen_random_uuid(), t, w, 'DOOR-01', NULL, false, u),
		       (gen_random_uuid(), t, w, repeat('9', 20), repeat('n', 60), true, u);
		INSERT INTO "dock_schedules" ("id","tenant_id","warehouse_id","slot_minutes","opens_minute","closes_minute","open_days","grace_minutes","updated_by")
		VALUES (gen_random_uuid(), t, w, 30, 540, 1080, 63, 15, u),
		       (gen_random_uuid(), t, gen_random_uuid(), 60, 0, 1440, 127, 0, u),
		       (gen_random_uuid(), t, gen_random_uuid(), 15, 375, 1425, 1, 120, u);
		INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","dock_door_id","starts_at","ends_at","grace_minutes","booked_by")
		VALUES (a, t, w, 'DA-0001', d, '2026-10-29T05:00:00Z', '2026-10-29T06:00:00Z', 15, u);
		INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","dock_door_id","starts_at","ends_at","grace_minutes","client_id",
			"vehicle_no","transporter_name","note","booked_by")
		VALUES (gen_random_uuid(), t, w, 'DA-123456789', d, '2026-10-29T06:00:00Z', '2026-10-29T14:00:00Z', 0, gen_random_uuid(),
			'KA01AB1234', repeat('T', 80), repeat('n', 500), u);
		INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","status","dock_door_id","starts_at","ends_at","grace_minutes",
			"gate_in_id","linked_at","linked_by","booked_by")
		VALUES (gen_random_uuid(), t, w, 'DA-0003', 'arrived', d, '2026-10-30T05:00:00Z', '2026-10-30T05:15:00Z', 120, g, now(), u, u);
		INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","status","dock_door_id","starts_at","ends_at","grace_minutes",
			"cancelled_at","cancelled_by","cancel_reason","booked_by")
		VALUES (gen_random_uuid(), t, w, 'DA-0004', 'cancelled', d, '2026-10-30T05:00:00Z', '2026-10-30T05:30:00Z', 15, now(), u, repeat('r', 200), u);
		INSERT INTO "dock_appointment_documents" ("id","tenant_id","appointment_id","position","po_id","asn_id")
		VALUES (gen_random_uuid(), t, a, 0, gen_random_uuid(), NULL),
		       (gen_random_uuid(), t, a, 9, NULL, gen_random_uuid());
		RAISE EXCEPTION USING ERRCODE = 'P0110', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0110: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0110' THEN
			NULL;
	END;
	-- (2) refused shapes: a valid base row of the probe's table, then one change.
	FOREACH probe IN ARRAY ARRAY[
		'door code lower-case', 'door code 21', 'door code with a space', 'door name blank', 'door name 61',
		'door name untrimmed', 'door duplicate code',
		'slot 45', 'opens after closes', 'closes past 24:00', 'opens negative', 'off the grid', 'no open day',
		'open days 128', 'schedule grace 121', 'schedule grace negative', 'schedule duplicate warehouse',
		'appointment code lower-case', 'appointment code 3 digits', 'unknown status', 'empty window',
		'window over 8 hours', 'appointment grace 121', 'vehicle lower-case', 'transporter 81',
		'transporter untrimmed', 'note blank', 'note 501', 'arrived without gate-in', 'gate-in while booked',
		'link without linked_at', 'cancelled without reason', 'reason while booked', 'reason 201',
		'appointment duplicate code', 'appointment duplicate gate-in',
		'document with neither', 'document with both', 'document position 10', 'document duplicate position'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'door code lower-case' THEN 'dock_doors_code_format'
			WHEN 'door code 21' THEN 'dock_doors_code_format'
			WHEN 'door code with a space' THEN 'dock_doors_code_format'
			WHEN 'door name blank' THEN 'dock_doors_name_length'
			WHEN 'door name 61' THEN 'dock_doors_name_length'
			WHEN 'door name untrimmed' THEN 'dock_doors_name_length'
			WHEN 'door duplicate code' THEN 'dock_doors_tenant_warehouse_code_unique'
			WHEN 'slot 45' THEN 'dock_schedules_slot_check'
			WHEN 'opens after closes' THEN 'dock_schedules_hours_range'
			WHEN 'closes past 24:00' THEN 'dock_schedules_hours_range'
			WHEN 'opens negative' THEN 'dock_schedules_hours_range'
			WHEN 'off the grid' THEN 'dock_schedules_hours_on_grid'
			WHEN 'no open day' THEN 'dock_schedules_open_days_range'
			WHEN 'open days 128' THEN 'dock_schedules_open_days_range'
			WHEN 'schedule grace 121' THEN 'dock_schedules_grace_range'
			WHEN 'schedule grace negative' THEN 'dock_schedules_grace_range'
			WHEN 'schedule duplicate warehouse' THEN 'dock_schedules_tenant_warehouse_unique'
			WHEN 'appointment code lower-case' THEN 'dock_appointments_code_format'
			WHEN 'appointment code 3 digits' THEN 'dock_appointments_code_format'
			WHEN 'unknown status' THEN 'dock_appointments_status_check'
			WHEN 'empty window' THEN 'dock_appointments_window_check'
			WHEN 'window over 8 hours' THEN 'dock_appointments_window_check'
			WHEN 'appointment grace 121' THEN 'dock_appointments_grace_range'
			WHEN 'vehicle lower-case' THEN 'dock_appointments_vehicle_no_format'
			WHEN 'transporter 81' THEN 'dock_appointments_transporter_name_length'
			WHEN 'transporter untrimmed' THEN 'dock_appointments_transporter_name_length'
			WHEN 'note blank' THEN 'dock_appointments_note_length'
			WHEN 'note 501' THEN 'dock_appointments_note_length'
			WHEN 'arrived without gate-in' THEN 'dock_appointments_arrived_pairing'
			WHEN 'gate-in while booked' THEN 'dock_appointments_arrived_pairing'
			WHEN 'link without linked_at' THEN 'dock_appointments_arrived_pairing'
			WHEN 'cancelled without reason' THEN 'dock_appointments_cancelled_pairing'
			WHEN 'reason while booked' THEN 'dock_appointments_cancelled_pairing'
			WHEN 'reason 201' THEN 'dock_appointments_cancel_reason_length'
			WHEN 'appointment duplicate code' THEN 'dock_appointments_tenant_code_unique'
			WHEN 'appointment duplicate gate-in' THEN 'dock_appointments_tenant_gate_in_unique'
			WHEN 'document with neither' THEN 'dock_appointment_documents_one_document'
			WHEN 'document with both' THEN 'dock_appointment_documents_one_document'
			WHEN 'document position 10' THEN 'dock_appointment_documents_position_range'
			ELSE 'dock_appointment_documents_tenant_appointment_position_unique'
		END;
		BEGIN
			r := gen_random_uuid();
			n := n + 1;
			IF probe LIKE 'door %' THEN
				INSERT INTO "dock_doors" ("id","tenant_id","warehouse_id","code","created_by")
				VALUES (r, t, w, 'P-' || n, u);
			ELSIF probe IN ('slot 45', 'opens after closes', 'closes past 24:00', 'opens negative', 'off the grid', 'no open day',
			                'open days 128', 'schedule grace 121', 'schedule grace negative', 'schedule duplicate warehouse') THEN
				INSERT INTO "dock_schedules" ("id","tenant_id","warehouse_id","slot_minutes","opens_minute","closes_minute","open_days","grace_minutes","updated_by")
				VALUES (r, t, w, 30, 540, 1080, 63, 15, u);
			ELSIF probe LIKE 'document %' THEN
				INSERT INTO "dock_appointment_documents" ("id","tenant_id","appointment_id","position","po_id")
				VALUES (r, t, a, 0, gen_random_uuid());
			ELSE
				INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","dock_door_id","starts_at","ends_at","grace_minutes","booked_by")
				VALUES (r, t, w, 'DA-' || lpad((1000 + n)::text, 4, '0'), d, '2026-10-29T05:00:00Z', '2026-10-29T05:30:00Z', 15, u);
				IF probe = 'reason 201' THEN
					UPDATE "dock_appointments" SET "status" = 'cancelled', "cancelled_at" = now(), "cancelled_by" = u, "cancel_reason" = 'Vendor postponed' WHERE "id" = r;
				END IF;
			END IF;
			CASE probe
				WHEN 'door code lower-case' THEN UPDATE "dock_doors" SET "code" = 'd-3' WHERE "id" = r;
				WHEN 'door code 21' THEN UPDATE "dock_doors" SET "code" = repeat('D', 21) WHERE "id" = r;
				WHEN 'door code with a space' THEN UPDATE "dock_doors" SET "code" = 'D 3' WHERE "id" = r;
				WHEN 'door name blank' THEN UPDATE "dock_doors" SET "name" = '' WHERE "id" = r;
				WHEN 'door name 61' THEN UPDATE "dock_doors" SET "name" = repeat('n', 61) WHERE "id" = r;
				WHEN 'door name untrimmed' THEN UPDATE "dock_doors" SET "name" = ' North' WHERE "id" = r;
				WHEN 'door duplicate code' THEN
					INSERT INTO "dock_doors" ("id","tenant_id","warehouse_id","code","created_by") VALUES (gen_random_uuid(), t, w, 'P-' || n, u);
				WHEN 'slot 45' THEN UPDATE "dock_schedules" SET "slot_minutes" = 45 WHERE "id" = r;
				WHEN 'opens after closes' THEN UPDATE "dock_schedules" SET "opens_minute" = 600, "closes_minute" = 540 WHERE "id" = r;
				WHEN 'closes past 24:00' THEN UPDATE "dock_schedules" SET "closes_minute" = 1470 WHERE "id" = r;
				WHEN 'opens negative' THEN UPDATE "dock_schedules" SET "opens_minute" = -30 WHERE "id" = r;
				WHEN 'off the grid' THEN UPDATE "dock_schedules" SET "opens_minute" = 550 WHERE "id" = r;
				WHEN 'no open day' THEN UPDATE "dock_schedules" SET "open_days" = 0 WHERE "id" = r;
				WHEN 'open days 128' THEN UPDATE "dock_schedules" SET "open_days" = 128 WHERE "id" = r;
				WHEN 'schedule grace 121' THEN UPDATE "dock_schedules" SET "grace_minutes" = 121 WHERE "id" = r;
				WHEN 'schedule grace negative' THEN UPDATE "dock_schedules" SET "grace_minutes" = -1 WHERE "id" = r;
				WHEN 'schedule duplicate warehouse' THEN
					INSERT INTO "dock_schedules" ("id","tenant_id","warehouse_id","slot_minutes","opens_minute","closes_minute","open_days","grace_minutes","updated_by")
					VALUES (gen_random_uuid(), t, w, 60, 540, 1080, 63, 15, u);
				WHEN 'appointment code lower-case' THEN UPDATE "dock_appointments" SET "code" = 'da-0001' WHERE "id" = r;
				WHEN 'appointment code 3 digits' THEN UPDATE "dock_appointments" SET "code" = 'DA-001' WHERE "id" = r;
				WHEN 'unknown status' THEN UPDATE "dock_appointments" SET "status" = 'parked' WHERE "id" = r;
				WHEN 'empty window' THEN UPDATE "dock_appointments" SET "ends_at" = "starts_at" WHERE "id" = r;
				WHEN 'window over 8 hours' THEN UPDATE "dock_appointments" SET "ends_at" = "starts_at" + interval '8 hours 1 minute' WHERE "id" = r;
				WHEN 'appointment grace 121' THEN UPDATE "dock_appointments" SET "grace_minutes" = 121 WHERE "id" = r;
				WHEN 'vehicle lower-case' THEN UPDATE "dock_appointments" SET "vehicle_no" = 'ka01ab1234' WHERE "id" = r;
				WHEN 'transporter 81' THEN UPDATE "dock_appointments" SET "transporter_name" = repeat('T', 81) WHERE "id" = r;
				WHEN 'transporter untrimmed' THEN UPDATE "dock_appointments" SET "transporter_name" = 'VRL ' WHERE "id" = r;
				WHEN 'note blank' THEN UPDATE "dock_appointments" SET "note" = '' WHERE "id" = r;
				WHEN 'note 501' THEN UPDATE "dock_appointments" SET "note" = repeat('n', 501) WHERE "id" = r;
				WHEN 'arrived without gate-in' THEN UPDATE "dock_appointments" SET "status" = 'arrived' WHERE "id" = r;
				WHEN 'gate-in while booked' THEN UPDATE "dock_appointments" SET "gate_in_id" = gen_random_uuid(), "linked_at" = now(), "linked_by" = u WHERE "id" = r;
				WHEN 'link without linked_at' THEN UPDATE "dock_appointments" SET "status" = 'arrived', "gate_in_id" = gen_random_uuid(), "linked_by" = u WHERE "id" = r;
				WHEN 'cancelled without reason' THEN UPDATE "dock_appointments" SET "status" = 'cancelled', "cancelled_at" = now(), "cancelled_by" = u WHERE "id" = r;
				WHEN 'reason while booked' THEN UPDATE "dock_appointments" SET "cancel_reason" = 'x' WHERE "id" = r;
				WHEN 'reason 201' THEN UPDATE "dock_appointments" SET "cancel_reason" = repeat('r', 201) WHERE "id" = r;
				WHEN 'appointment duplicate code' THEN
					INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","dock_door_id","starts_at","ends_at","grace_minutes","booked_by")
					VALUES (gen_random_uuid(), t, w, 'DA-' || lpad((1000 + n)::text, 4, '0'), d, '2026-10-29T06:00:00Z', '2026-10-29T06:30:00Z', 15, u);
				WHEN 'appointment duplicate gate-in' THEN
					UPDATE "dock_appointments" SET "status" = 'arrived', "gate_in_id" = g, "linked_at" = now(), "linked_by" = u WHERE "id" = r;
					INSERT INTO "dock_appointments" ("id","tenant_id","warehouse_id","code","status","dock_door_id","starts_at","ends_at","grace_minutes",
						"gate_in_id","linked_at","linked_by","booked_by")
					VALUES (gen_random_uuid(), t, w, 'DA-9999', 'arrived', d, '2026-10-29T06:00:00Z', '2026-10-29T06:30:00Z', 15, g, now(), u, u);
				WHEN 'document with neither' THEN UPDATE "dock_appointment_documents" SET "po_id" = NULL WHERE "id" = r;
				WHEN 'document with both' THEN UPDATE "dock_appointment_documents" SET "asn_id" = gen_random_uuid() WHERE "id" = r;
				WHEN 'document position 10' THEN UPDATE "dock_appointment_documents" SET "position" = 10 WHERE "id" = r;
				WHEN 'document duplicate position' THEN
					INSERT INTO "dock_appointment_documents" ("id","tenant_id","appointment_id","position","asn_id") VALUES (gen_random_uuid(), t, a, 0, gen_random_uuid());
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0110', MESSAGE = 'probe accepted';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0110' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0110: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "dock_doors" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "dock_schedules" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "dock_appointments" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "dock_appointment_documents" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0110: a probe row survived.';
	END IF;
END $$;
